from taf.sw.dcap.rd.services.cm.cm_base import CM
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.start_trace_body_v2 import StartTraceBodyV2
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.start_trace_body_v2_trace_profiles import \
    StartTraceBodyV2TraceProfiles
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CMv2(CM):

    def __init__(self, con_details):
        super(CMv2, self).__init__(con_details)
        self._bts_trace_profile = None

    def create_bts(self, host, port, username, password, bts_alias, credential_region_Id, timeout):
        self._create_bts = self.api_client.create_bts_v2(
            bts_login_with_optional_credentials={'alias': bts_alias, 'host': host, 'port': port,
                                                 'username': username, 'password': password,
                                                 'credentialRegionId': credential_region_Id},
            _request_timeout=timeout)
        return self._create_bts

    def create_multiple_bts(self, bts_info, timeout):
        create_multiple_bts = []
        for bts in bts_info:
            _create_multiple_bts = self.api_client.create_multiple_bts_v2(
                bts_login_with_optional_credentials={'alias': bts['alias'],
                                                     'host': bts['host'],
                                                     'port': bts['port'],
                                                     'username': bts['username'],
                                                     'password': bts['password'],
                                                     'credentialRegionId': bts['credential_region_Id']},
                _request_timeout=timeout)
            create_multiple_bts.append(_create_multiple_bts)
        return create_multiple_bts

    @staticmethod
    def gnb_enb_trace_body_v2(trace_profiles):
        if not isinstance(trace_profiles, list):
            trace_profiles = [trace_profiles]
        gnb_trace_profiles = next((p for p in trace_profiles if p.get('tracers', [{}])[0].get('type') == 'GNB'), None)
        enb_trace_profiles = next((p for p in trace_profiles if p.get('tracers', [{}])[0].get('type') == 'ENB'), None)
        bts_trace_profiles = next((p for p in trace_profiles if p.get('tracers', [{}])[0].get('type') == 'BTS'), None)
        vcu_trace_profiles = next((p for p in trace_profiles if p.get('tracers', [{}])[0].get('type') == 'VCU'), None)
        vdu_trace_profiles = next(
            (p for p in trace_profiles if p.get('tracers', [{}])[0].get('type') not in ['GNB', 'ENB', 'BTS', 'VCU']),
            None)
        return gnb_trace_profiles, enb_trace_profiles, bts_trace_profiles, vcu_trace_profiles, vdu_trace_profiles

    def start_trace_from(self, bts, force=None, tag=None, trace_profiles=None,
                         duration=None, wait_for_activation=False, timeout=400):
        gnb_trace_profiles, enb_trace_profiles, bts_trace_profiles, vcu_trace_profiles, vcu_trace_profiles = \
            self.gnb_enb_trace_body_v2(trace_profiles=trace_profiles)
        trace_profiles = StartTraceBodyV2TraceProfiles(gnb=gnb_trace_profiles, bts=bts_trace_profiles,
                                                       enb=enb_trace_profiles)
        start_trace_body = StartTraceBodyV2(force=force, tag=tag, bts=bts,
                                            trace_profiles=trace_profiles, duration=duration)
        self.api_client.new_trace_v2(start_trace_body_v2=start_trace_body)
        return self.wait_for_start_trace_activation(wait_for_activation=wait_for_activation, timeout=timeout)

    @staticmethod
    def _get_gnb_and_lte_custom_tracers_info(gnb_lte_trace_profiles):
        gnb_lte_custom = []
        for i in range(len(gnb_lte_trace_profiles)):
            custom_profile = [
                CM._get_tracers_info_dict(custom_trace)
                for custom_trace in gnb_lte_trace_profiles[i].get('tracers')
            ]
            trace_profiles = {
                'id': gnb_lte_trace_profiles[i]['id'],
                'name': gnb_lte_trace_profiles[i]['name'],
                'tracers': custom_profile
            }
            gnb_lte_custom.append(trace_profiles)
        return gnb_lte_custom

    def start_trace(self, bts, tag, duration, force, gnb_trace_profile, enb_trace_profile, bts_trace_profile,
                    gnb_custom_profile, enb_custom_profile, wait_for_activation, control_plane_interface, timeout):
        trace_profiles = self.start_trace_profile_selection(gnb_trace_profile=gnb_trace_profile,
                                                            enb_trace_profile=enb_trace_profile,
                                                            gnb_custom_profile=gnb_custom_profile,
                                                            enb_custom_profile=enb_custom_profile,
                                                            control_plane_interface=control_plane_interface)
        return self.start_trace_from(force=force, tag=tag, bts=bts,
                                     trace_profiles=trace_profiles, duration=duration,
                                     wait_for_activation=wait_for_activation, timeout=timeout)

    def get_all_bts_info(self, timeout):
        return self.api_client.get_all_bts_v2(_request_timeout=timeout)

    def get_bts_by_id(self, bts_id, timeout):
        bts_id = self._get_bts_id(bts_id=bts_id)
        return self.api_client.get_bts_by_id_v2(bts_id=bts_id, _request_timeout=timeout)

    def get_trace_info_by_id(self, trace_id, timeout):
        trace_id = self._get_trace_id(trace_id)
        return self.api_client.get_trace_info_by_id_v2(trace_id=trace_id, _request_timeout=timeout)

    def get_5g_profiles(self, timeout):
        return self.api_client.get_profiles5_gv2(_request_timeout=timeout)

    def get_lte_profiles(self, timeout):
        return self.api_client.get_profiles4_gv2(_request_timeout=timeout)

    def get_tracers(self, timeout):
        return self.api_client.get_tracers_v2(_request_timeout=timeout)
